import torch

def top_k_filter(logits, k):
    if k <= 0 or k >= logits.size(-1):
        return logits
    threshold = torch.topk(logits, k, dim=-1).values[..., -1, None]
    return logits.masked_fill(logits < threshold, float("-inf"))

import torch

def rotate_half(x):
    x1 = x[..., ::2]
    x2 = x[..., 1::2]
    y = torch.stack((-x2, x1), dim=-1)
    return y.flatten(-2)

def apply_rope(x, cos, sin):
    # cos/sin are broadcastable to x and repeated across each pair.
    return x * cos + rotate_half(x) * sin

import torch

def causal_mask(T, device=None):
    return torch.ones(T, T, dtype=torch.bool, device=device).tril()

import torch

def append_kv(k_cache, v_cache, k_new, v_new):
    if k_cache is None:
        return k_new, v_new
    return (torch.cat([k_cache, k_new], dim=-2),
            torch.cat([v_cache, v_new], dim=-2))

import torch

def sample_token(logits, temperature=1.0):
    if temperature <= 0:
        return logits.argmax(dim=-1)
    probs = torch.softmax(logits / temperature, dim=-1)
    return torch.multinomial(probs, num_samples=1).squeeze(-1)

