import torch.nn.functional as F

def reward_pair_loss(chosen, rejected):
    return -F.logsigmoid(chosen - rejected).mean()

import torch

def ppo_ratio(new_logprob, old_logprob):
    return torch.exp(new_logprob - old_logprob)

import torch

def ppo_clipped_objective(new_logp, old_logp, advantage, eps=0.2):
    ratio = torch.exp(new_logp - old_logp)
    s1 = ratio * advantage
    s2 = torch.clamp(ratio, 1 - eps, 1 + eps) * advantage
    return torch.minimum(s1, s2).mean()

import torch

def grpo_advantage(rewards, eps=1e-6):
    mean = rewards.mean(dim=-1, keepdim=True)
    std = rewards.std(dim=-1, keepdim=True, unbiased=False)
    return (rewards - mean) / (std + eps)
